// File: internal/distributed/proxy/httpserver/request_v2.go, lines 690-703
type CollectionReq struct {
	DbName           string                 `json:"dbName"`
	CollectionName   string                 `json:"collectionName" binding:"required"`
	Dimension        int32                  `json:"dimension"`
	IDType           string                 `json:"idType"`
	AutoID           bool                   `json:"autoID"`
	MetricType       string                 `json:"metricType"`
	PrimaryFieldName string                 `json:"primaryFieldName"`
	VectorFieldName  string                 `json:"vectorFieldName"`
	Schema           CollectionSchema       `json:"schema"`
	IndexParams      []IndexParam           `json:"indexParams"`
	Params           map[string]interface{} `json:"params"`
	Description      string                 `json:"description"`
	// NOTE: No 'vectorFieldType' field defined
}

// File: internal/distributed/proxy/httpserver/handler_v2.go, lines 1904-1931 (quick-setup schema generation)
schema, err = proto.Marshal(&schemapb.CollectionSchema{
	Name: httpReq.CollectionName,
	Fields: []*schemapb.FieldSchema{
		{
			FieldID:      common.StartOfUserFieldID,
			Name:         httpReq.PrimaryFieldName,
			IsPrimaryKey: true,
			DataType:     idDataType,
			AutoID:       httpReq.AutoID,
			TypeParams:   idParams,
		},
		{
			FieldID:      common.StartOfUserFieldID + 1,
			Name:         httpReq.VectorFieldName,
			IsPrimaryKey: false,
			DataType:     schemapb.DataType_FloatVector,  // HARDCODED FloatVector, not configurable
			TypeParams: []*commonpb.KeyValuePair{
				{
					Key:   Dim,
					Value: strconv.FormatInt(int64(httpReq.Dimension), 10),
				},
			},
			AutoID: DisableAutoID,
		},
	},
	EnableDynamicField: enableDynamic,
	Description:        httpReq.Description,
})
